int lengthOfLongestSubstring(const std::string& s) {
    std::vector<int> lastIndex(256, -1);
    int maxLen = 0, start = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        unsigned char c = s[i];
        if (lastIndex[c] >= start) {
            start = lastIndex[c] + 1;
        }
        lastIndex[c] = i;
        maxLen = std::max(maxLen, i - start + 1);
    }
    return maxLen;
}

int main() {
